// src/pages/Tareas.jsx
import React from "react";
import { Link } from "react-router-dom";
import Layout from "../components/Layout";
import "../pages/PageCommon.css";

export default function Tareas() {
   const tareas = [
     {
       id: 1.2,
       title: "Mapa Conceptual e Investigación",
       desc: "Análisis y documentación de conceptos fundamentales del aseguramiento de calidad",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Investigación",
       date: "2024-01-15"
     },
     {
       id: 2,
       title: "Análisis Crítico de Estándares Internacionales",
       desc: "Estudio detallado de normas ISO/IEC para calidad de software",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Análisis",
       date: "2024-02-01"
     },
     {
       id: 3,
       title: "Guía OWASP y Casos de Prueba",
       desc: "Investigación completa de vulnerabilidades web y técnicas de testing",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Seguridad",
       date: "2024-02-15"
     },
     {
       id: 4,
       title: "Tipos de Prueba",
       desc: "Clasificación y aplicación de diferentes tipos de pruebas de software",
       status: "in-progress",
       priority: "medium",
       progress: 75,
       category: "Testing",
       date: "2024-03-01"
     },
     {
       id: 5,
       title: "Técnicas de Pruebas",
       desc: "Metodologías avanzadas para pruebas funcionales y no funcionales",
       status: "pending",
       priority: "medium",
       progress: 25,
       category: "Testing",
       date: "2024-03-15"
     },
     {
       id: 6,
       title: "Unit Test - JavaScript/TypeScript",
       desc: "Desarrollo de proyecto completo con pruebas unitarias y cobertura",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Desarrollo",
       date: "2024-04-01"
     },
     {
       id: 7,
       title: "Herramientas de Testing",
       desc: "Análisis completo de herramientas para pruebas automatizadas",
       status: "in-progress",
       priority: "medium",
       progress: 60,
       category: "Herramientas",
       date: "2024-04-15"
     },
     {
       id: 8,
       title: "Registro de Errores",
       desc: "Sistema de seguimiento y gestión de bugs reportados",
       status: "completed",
       priority: "medium",
       progress: 100,
       category: "Gestión",
       date: "2024-05-01"
     },
     {
       id: 9,
       title: "Certificado QA",
       desc: "Certificación profesional en Quality Assurance",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Certificación",
       date: "2024-05-15"
     },
     {
       id: 10,
       title: "Parcial 2 - Tercera Serie",
       desc: "Evaluación práctica de conocimientos adquiridos",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Evaluación",
       date: "2024-06-01"
     },
     {
       id: 1.1,
       title: "Calculadora - Unit Test",
       desc: "Proyecto C# con pruebas unitarias y manejo de errores",
       status: "completed",
       priority: "medium",
       progress: 100,
       category: "Desarrollo",
       date: "2024-01-30"
     },
   ];

   // Calcular métricas
   const metrics = {
     total: tareas.length,
     completed: tareas.filter(t => t.status === 'completed').length,
     inProgress: tareas.filter(t => t.status === 'in-progress').length,
     pending: tareas.filter(t => t.status === 'pending').length,
   };

   const getStatusIcon = (status) => {
     switch(status) {
       case 'completed': return '✅';
       case 'in-progress': return '🔄';
       case 'pending': return '⏳';
       default: return '📋';
     }
   };

   const getPriorityIcon = (priority) => {
     switch(priority) {
       case 'high': return '🔴';
       case 'medium': return '🟡';
       case 'low': return '🟢';
       default: return '⚪';
     }
   };

  // Organizar tareas por estado
  const tareasPorEstado = {
    completed: tareas.filter(t => t.status === 'completed'),
    'in-progress': tareas.filter(t => t.status === 'in-progress'),
    pending: tareas.filter(t => t.status === 'pending'),
  };

  const getColumnIcon = (status) => {
    switch(status) {
      case 'completed': return '✅';
      case 'in-progress': return '🔄';
      case 'pending': return '⏳';
      default: return '📋';
    }
  };

  const getColumnColor = (status) => {
    switch(status) {
      case 'completed': return 'linear-gradient(135deg, #10b981, #059669)';
      case 'in-progress': return 'linear-gradient(135deg, #f59e0b, #d97706)';
      case 'pending': return 'linear-gradient(135deg, #6b7280, #4b5563)';
      default: return 'linear-gradient(135deg, #6366f1, #4f46e5)';
    }
  };

  return (
    <Layout>
      <div className="tareas-container">
        {/* Header del Kanban */}
        <div className="kanban-header">
          <h1 className="kanban-main-title">
            📋 Kanban de <span>Tareas</span>
          </h1>
          <p className="kanban-subtitle">
            Tablero organizativo con flujo de trabajo visual y seguimiento en tiempo real
          </p>
        </div>

        {/* Métricas Compactas */}
        <div className="dashboard-metrics" style={{marginBottom: '2rem'}}>
          <div className="metric-card" style={{background: 'rgba(255,255,255,0.1)', border: '1px solid rgba(255,255,255,0.2)'}}>
            <div className="metric-icon total" style={{background: 'rgba(255,255,255,0.2)'}}>
              📊
            </div>
            <div className="metric-value" style={{color: 'white'}}>{metrics.total}</div>
            <div className="metric-label" style={{color: 'rgba(255,255,255,0.8)'}}>Total</div>
          </div>

          <div className="metric-card" style={{background: 'rgba(16,185,129,0.2)', border: '1px solid rgba(16,185,129,0.3)'}}>
            <div className="metric-icon completed">
              ✅
            </div>
            <div className="metric-value" style={{color: '#10b981'}}>{metrics.completed}</div>
            <div className="metric-label" style={{color: 'rgba(255,255,255,0.8)'}}>Completadas</div>
          </div>

          <div className="metric-card" style={{background: 'rgba(245,158,11,0.2)', border: '1px solid rgba(245,158,11,0.3)'}}>
            <div className="metric-icon in-progress">
              🔄
            </div>
            <div className="metric-value" style={{color: '#f59e0b'}}>{metrics.inProgress}</div>
            <div className="metric-label" style={{color: 'rgba(255,255,255,0.8)'}}>En Progreso</div>
          </div>

          <div className="metric-card" style={{background: 'rgba(107,114,128,0.2)', border: '1px solid rgba(107,114,128,0.3)'}}>
            <div className="metric-icon pending">
              ⏳
            </div>
            <div className="metric-value" style={{color: '#6b7280'}}>{metrics.pending}</div>
            <div className="metric-label" style={{color: 'rgba(255,255,255,0.8)'}}>Pendientes</div>
          </div>
        </div>

        {/* Kanban Board */}
        <div className="kanban-board">
          {Object.entries(tareasPorEstado).map(([estado, tareasEstado]) => (
            <div key={estado} className="kanban-column">
              <div className="kanban-header" style={{background: getColumnColor(estado)}}>
                <h3 className="kanban-title">
                  {getColumnIcon(estado)} {estado === 'completed' ? 'Completadas' : estado === 'in-progress' ? 'En Progreso' : 'Pendientes'}
                </h3>
                <span className="kanban-count">{tareasEstado.length}</span>
              </div>

              <div className="kanban-body">
                {tareasEstado.map((tarea) => (
                  <Link
                    key={tarea.id}
                    to={`/tareas/${tarea.id}`}
                    style={{ textDecoration: "none", color: "inherit" }}
                  >
                    <div className="kanban-card">
                      <div className="kanban-card-header">
                        <h4 className="kanban-card-title">{tarea.title}</h4>
                        <span className="kanban-card-id">#{tarea.id}</span>
                      </div>

                      <p className="kanban-card-desc">{tarea.desc}</p>

                      <div className="kanban-card-footer">
                        <span className="kanban-card-date">
                          📅 {tarea.date}
                        </span>
                        <span className={`kanban-card-priority priority-kanban-${tarea.priority}`}>
                          {tarea.priority}
                        </span>
                      </div>
                    </div>
                  </Link>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </Layout>
  );
}
